--liquibase formatted sql

-- First version of the welcome letters, one per new account type. Change a letter by inserting a new VERSION_NO
-- and setting ACTIVE on it (the highest active version is used); rows already sent keep their own copy.
-- Placeholders are Thymeleaf attributes (th:text), so customer data is HTML-escaped when the letter is built.
--changeset bank:com-003-welcome-templates
INSERT INTO LETTER_TEMPLATE (ID, TEMPLATE_CODE, ACCOUNT_TYPE, VERSION_NO, SUBJECT, BODY_HTML, ACTIVE)
VALUES (LETTER_TEMPLATE_SEQ.NEXTVAL, 'WELCOME_SAVINGS_PLUS', 'SAVINGS_PLUS', 1,
        'Your account is now [[${toTypeLabel}]]', '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2933"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 0"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px"><tr><td style="background:#0b3d91;color:#ffffff;padding:24px 32px;font-size:20px;font-weight:bold;border-radius:8px 8px 0 0">Example Bank</td></tr><tr><td style="padding:32px;font-size:16px;line-height:1.5"><p style="margin:0 0 16px">Dear <span th:text="${customerName}">Customer</span>,</p><p style="margin:0 0 16px">Your account <strong th:text="${maskedAccountNo}">ending 0000</strong> has been upgraded from <span th:text="${fromTypeLabel}">your current account type</span> to <strong th:text="${toTypeLabel}">the new account type</strong>, effective <span th:text="${businessDate}">today</span>.</p><p style="margin:0 0 8px">What this gives you:</p><ul style="margin:0 0 16px;padding-left:20px"><li style="margin:0 0 8px">A higher interest rate on your balance</li><li style="margin:0 0 8px">More free transfers each month</li><li style="margin:0 0 8px">Priority help from our support team</li></ul><p style="margin:0 0 16px">You do not need to do anything. Your account number, cards and online banking login stay the same. The full terms are in the account terms for your new account type.</p><p style="margin:0 0 16px">If you did not expect this change, please call the number on the back of your card.</p><p style="margin:0">Kind regards,<br>Customer Care</p></td></tr><tr><td style="padding:16px 32px;background:#f9fafb;color:#6b7280;font-size:12px;border-radius:0 0 8px 8px">This is a service message about your account, sent to the email address we hold for you. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', 1);
INSERT INTO LETTER_TEMPLATE (ID, TEMPLATE_CODE, ACCOUNT_TYPE, VERSION_NO, SUBJECT, BODY_HTML, ACTIVE)
VALUES (LETTER_TEMPLATE_SEQ.NEXTVAL, 'WELCOME_CURRENT_PLUS', 'CURRENT_PLUS', 1,
        'Your account is now [[${toTypeLabel}]]', '<!DOCTYPE html><html><body style="margin:0;padding:0;background:#f4f5f7;font-family:Arial,Helvetica,sans-serif;color:#1f2933"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f5f7;padding:24px 0"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;background:#ffffff;border-radius:8px"><tr><td style="background:#0b3d91;color:#ffffff;padding:24px 32px;font-size:20px;font-weight:bold;border-radius:8px 8px 0 0">Example Bank</td></tr><tr><td style="padding:32px;font-size:16px;line-height:1.5"><p style="margin:0 0 16px">Dear <span th:text="${customerName}">Customer</span>,</p><p style="margin:0 0 16px">Your account <strong th:text="${maskedAccountNo}">ending 0000</strong> has been upgraded from <span th:text="${fromTypeLabel}">your current account type</span> to <strong th:text="${toTypeLabel}">the new account type</strong>, effective <span th:text="${businessDate}">today</span>.</p><p style="margin:0 0 8px">What this gives you:</p><ul style="margin:0 0 16px;padding-left:20px"><li style="margin:0 0 8px">A higher arranged overdraft limit</li><li style="margin:0 0 8px">No fee on card payments abroad</li><li style="margin:0 0 8px">Priority help from our support team</li></ul><p style="margin:0 0 16px">You do not need to do anything. Your account number, cards and online banking login stay the same. The full terms are in the account terms for your new account type.</p><p style="margin:0 0 16px">If you did not expect this change, please call the number on the back of your card.</p><p style="margin:0">Kind regards,<br>Customer Care</p></td></tr><tr><td style="padding:16px 32px;background:#f9fafb;color:#6b7280;font-size:12px;border-radius:0 0 8px 8px">This is a service message about your account, sent to the email address we hold for you. Please do not reply to it.</td></tr></table></td></tr></table></body></html>', 1);
